//   Course Clips/ 3 - Hazy Maze Cave/ Areas 3-6, 3-7 & 3-8/3-7 Back GFX / layer 'Layer 3' / frame 2
void frame_4305_0(Activation& scope) {
    stop();
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope.self["warp2"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 2;
        }
        if (scope.self["warp3"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 3;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                _root["attachMovie"]("lefttransition", "lefttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            } else {
                _root["attachMovie"]("uptransition", "uptransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("lefttransition2", "3-2", 500, 1420, 500, 1420);
            } else if (scope["warpnum"] == 2) {
                _root["changecourse"]("lefttransition2", "3-2", 500, 1780, 500, 1780);
            } else {
                _root["changecourse"]("uptransition2", "3-2", 2120, 0, 2120, 0);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

